import fs from 'node:fs';
import path from 'node:path';

import { readSiteFiles } from './files.js';
import { toPosition } from './mdx.js';
import type { Site } from './types.js';

const readVariables = (config: string): Record<string, string> | undefined => {
  try {
    const { variables } = JSON.parse(config) as { variables?: unknown };
    return variables && typeof variables === 'object'
      ? (variables as Record<string, string>)
      : undefined;
  } catch {
    return undefined;
  }
};

/** Lists the site's pages and snippets; locate reads files from disk on demand. */
export const loadSite = async (
  baseDir: string,
  { selected, localSchema }: { selected?: ReadonlySet<string>; localSchema: boolean }
): Promise<Site> => {
  const files = await readSiteFiles(baseDir);
  const byPath = new Map<string, string | undefined>();
  const configFile = fs.existsSync(path.join(baseDir, 'docs.json')) ? 'docs.json' : 'mint.json';

  const read = (file: string) => {
    if (!byPath.has(file)) {
      try {
        byPath.set(file, fs.readFileSync(path.join(baseDir, file), 'utf-8'));
      } catch {
        byPath.set(file, undefined);
      }
    }
    return byPath.get(file);
  };

  return {
    baseDir,
    files,
    selected,
    configFile,
    variables: readVariables(read(configFile) ?? ''),
    localSchema,
    read,
    locate: (file, text) => {
      const content = read(file) ?? '';
      const offset = text ? content.indexOf(text) : -1;
      return offset === -1 ? {} : toPosition(content, offset);
    },
  };
};
